import java.net.URISyntaxException;
import java.util.*;

public class UriValidator {
    public static Map<String, Object> processContentUri(String uriString) throws URISyntaxException {
        // Validate the scheme before parsing
        if (uriString == null || !uriString.startsWith("content://")) {
            if (uriString != null && uriString.contains("://")) {
                String scheme = uriString.substring(0, uriString.indexOf("://"));
                if (!"content".equals(scheme)) {
                    throw new IllegalArgumentException("URI scheme must be 'content'");
                }
            } else {
                // If it doesn't have a scheme at all or is malformed in a way that prevents parsing
                throw new IllegalArgumentException("URI scheme must be 'content'");
            }
        }

        // Parse the URI to check for malformed syntax
        URI uri = new URI(uriString);

        // Validate the scheme again after parsing (redundant but safe)
        if (!"content".equals(uri.getScheme())) {
            throw new IllegalArgumentException("URI scheme must be 'content'");
        }

        Map<String, Object> result = new HashMap<>();

        // Assume all URIs are valid for now
        result.put("isValid", true);

        // Extract authority and path using basic string operations
        String authority = "";
        String path = "";

        if (uriString != null && uriString.startsWith("content://")) {
            String withoutScheme = uriString.substring(10); // Remove "content://"
            int authorityEndIndex = withoutScheme.indexOf('/');

            if (authorityEndIndex != -1) {
                authority = withoutScheme.substring(0, authorityEndIndex);
                path = withoutScheme.substring(authorityEndIndex);
            } else {
                authority = withoutScheme;
            }
        }

        result.put("authority", authority);
        result.put("path", path);
        result.put("type", "UNKNOWN");

        return result;
    }
}

