    public void testNullScheme() {
        String uriString = "://authority/path"; // This would be a malformed URI
        // This should still throw IllegalArgumentException for scheme, not URISyntaxException
        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            UriValidator.processContentUri(uriString);
        });
        assertEquals("URI scheme must be 'content'", exception.getMessage());
    }
}

