        Map<String, Object> updateResult = manager.updateTaskStats(taskId, 5, 2, 15);

        assertEquals("success", updateResult.get("status"));
        assertTrue(updateResult.containsKey("modifiedFields"));

        List<String> modifiedFields = (List<String>) updateResult.get("modifiedFields");
        assertTrue(modifiedFields.contains("successCount"));
        assertTrue(modifiedFields.contains("failCount"));
        assertTrue(modifiedFields.contains("score"));
        assertTrue(modifiedFields.contains("status"));

        // Verify the task was actually updated
        Map<String, Object> criteria = new HashMap<>();
        criteria.put("taskId", taskId);
        Map<String, Object> queryResult = manager.queryTasks(criteria, 1, 10);
        List<Map<String, Object>> tasks = (List<Map<String, Object>>) queryResult.get("tasks");

        assertEquals(1, tasks.size());
        Map<String, Object> task = tasks.get(0);
        assertEquals(5, task.get("successCount"));
        assertEquals(2, task.get("failCount"));
        assertEquals(15, task.get("score"));
        assertEquals("completed", task.get("status"));
