    @Test
    void testUpdateTaskStatsNoStatusChange() {
        TaskDatabaseManager manager = new TaskDatabaseManager();

        // Insert a task first
        Map<String, Object> insertResult = manager.insertTask(1, "Test Task", "Content", 123, "John");
        String taskId = (String) insertResult.get("taskId");

        // Update with zero success increment (should not change status)
        Map<String, Object> updateResult = manager.updateTaskStats(taskId, 0, 3, 0);

        assertEquals("success", updateResult.get("status"));

        List<String> modifiedFields = (List<String>) updateResult.get("modifiedFields");
        assertTrue(modifiedFields.contains("successCount"));
        assertTrue(modifiedFields.contains("failCount"));
        assertTrue(modifiedFields.contains("score"));
        assertFalse(modifiedFields.contains("status")); // Status should not be modified

        // Verify the task was updated but status remains pending
        Map<String, Object> criteria = new HashMap<>();
        criteria.put("taskId", taskId);
        Map<String, Object> queryResult = manager.queryTasks(criteria, 1, 10);
        List<Map<String, Object>> tasks = (List<Map<String, Object>>) queryResult.get("tasks");

