        Map<String, Object> task = tasks.get(0);
        assertEquals(0, task.get("successCount"));
        assertEquals(3, task.get("failCount"));
        assertEquals(0, task.get("score"));
        assertEquals("pending", task.get("status"));
    }

    @Test
    void testUpdateTaskStatsTaskNotFound() {
        TaskDatabaseManager manager = new TaskDatabaseManager();

        // Try to update a non-existent task
        Map<String, Object> updateResult = manager.updateTaskStats("non-existent-id", 5, 2, 15);

        assertEquals("error", updateResult.get("status"));
        assertTrue(updateResult.containsKey("message"));
        assertTrue(((String) updateResult.get("message")).contains("Task not found"));
    }

    @Test
    void testUpdateTaskStatsNegativeIncrements() {
        TaskDatabaseManager manager = new TaskDatabaseManager();

        // Insert a task first with some initial values
        Map<String, Object> insertResult = manager.insertTask(1, "Test Task", "Content", 123, "John");
        String taskId = (String) insertResult.get("taskId");

        // Update with negative increments
        Map<String, Object> updateResult = manager.updateTaskStats(taskId, -1, -1, -5);

        assertEquals("success", updateResult.get("status"));

        // Verify the task was updated with negative values
        Map<String, Object> criteria = new HashMap<>();
        criteria.put("taskId", taskId);
        Map<String, Object> queryResult = manager.queryTasks(criteria, 1, 10);
        List<Map<String, Object>> tasks = (List<Map<String, Object>>) queryResult.get("tasks");

        assertEquals(1, tasks.size());
        Map<String, Object> task = tasks.get(0);
        assertEquals(-1, task.get("successCount"));
        assertEquals(-1, task.get("failCount"));
        assertEquals(-5, task.get("score"));
        assertEquals("pending", task.get("status")); // Status should not change with negative success
    }
}

