import json
import re
import pandas as pd

def task_func(json_str):
    # Handle empty JSON string
    if not json_str or json_str.strip() == '':
        return pd.DataFrame()

    try:
        # Load JSON string into a dictionary
        data_dict = json.loads(json_str)
    except (json.JSONDecodeError, ValueError):
        # Return empty DataFrame if JSON is invalid
        return pd.DataFrame()

    # Handle empty dictionary case
    if not data_dict:
        return pd.DataFrame()

    # Helper function to process string values that represent numbers
    def process_string_number(s):
        # Check if string represents a number (int or float)
        if re.match(r'^-?\d+$', s):  # Integer pattern
            return int(s) * 2
        elif re.match(r'^-?\d*\.\d+$', s):  # Float pattern
            return float(s) * 2
        else:
            return s  # Return unchanged if not a number

    # Normalize the dictionary by doubling numerical values
    for key, value in data_dict.items():
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            data_dict[key] = value * 2
        elif isinstance(value, str):
            # Process string values that represent numbers
            data_dict[key] = process_string_number(value)
        elif isinstance(value, list):
            # Double numerical values in lists, process string numbers, but preserve booleans
            processed_list = []
            for v in value:
                if isinstance(v, (int, float)) and not isinstance(v, bool):
                    processed_list.append(v * 2)
                elif isinstance(v, str):
                    processed_list.append(process_string_number(v))
                else:
                    processed_list.append(v)
            data_dict[key] = processed_list

    # Convert scalar values to lists for DataFrame creation, but keep lists as single values
    for key, value in data_dict.items():
        if not isinstance(value, list):
            data_dict[key] = [value]
        else:
            # Wrap the list in another list so it becomes a single cell value
            data_dict[key] = [value]

    # Create a Pandas DataFrame from the dictionary
    df = pd.DataFrame(data_dict)

    # Convert numeric columns to float type where possible
    for col in df.columns:
        try:
            # Try to convert to numeric, coercing errors to NaN
            numeric_series = pd.to_numeric(df[col], errors='coerce')
            # If all values are successfully converted (no NaN from coercion), use the numeric version
            if not numeric_series.isna().any():
                df[col] = numeric_series.astype(float)
        except (ValueError, TypeError):
            # Keep original column if conversion fails
            pass

    return df

