def clip_to_bounds(array, bounds):
    import numpy as np

    lower, upper = bounds
    clipped_array = array.copy()

    # Handle scalar bounds (same bounds for all elements)
    if np.isscalar(lower) and np.isscalar(upper):
        clipped_array = np.clip(clipped_array, lower, upper)
    else:
        # Handle per-feature bounds
        lower = np.asarray(lower)
        upper = np.asarray(upper)

        if array.ndim != 2:
            raise ValueError(f"For non-scalar bounds, input array must be 2-dimensional. Got {array.ndim} dimensions.")

        if len(lower) != array.shape[1] or len(upper) != array.shape[1]:
            raise ValueError("Bounds dimensions must match the number of features in the array.")

        # Convert to float to handle non-integer bounds properly
        if not np.issubdtype(clipped_array.dtype, np.floating):
            clipped_array = clipped_array.astype(float)

        for feature in range(array.shape[1]):
            clipped_array[:, feature] = np.clip(array[:, feature], lower[feature], upper[feature])

    return clipped_array

