def get_path(root, path, default=None):
    if isinstance(path, str):
        path = path.split('.')

    # Handle empty path case
    if not path or (len(path) == 1 and path[0] == ''):
        return root

    cur = root
    for seg in path:
        try:
            cur = cur[seg]
        except (KeyError, IndexError):
            try:
                seg = int(seg)
                cur = cur[seg]
            except (ValueError, KeyError, IndexError, TypeError):
                return default
        except TypeError:
            try:
                seg = int(seg)
                cur = cur[seg]
            except (ValueError, KeyError, IndexError, TypeError):
                return default
    return cur

class PathAccessError(Exception):
    def __init__(self, exc, seg, path):
        self.exc = exc
        self.seg = seg
        self.path = path
        super(PathAccessError, self).__init__(str(exc))

def is_iterable(obj):
    try:
        iter(obj)
        return True
    except TypeError:
        return False

_UNSET = object()

def get_path(root, path, default=_UNSET):
    if isinstance(path, str):
        path = path.split('.')
    cur = root
    try:
        for seg in path:
            original_seg = seg
            try:
                cur = cur[seg]
            except (KeyError, IndexError) as exc:
                raise PathAccessError(exc, original_seg, path)
            except TypeError as exc:
                try:
                    seg = int(seg)
                    cur = cur[seg]
                except (ValueError, KeyError, IndexError, TypeError):
                    if not is_iterable(cur):
                        exc = TypeError('%r object is not indexable'
                                        % type(cur).__name__)
                    raise PathAccessError(exc, original_seg, path)
    except PathAccessError:
        if default is _UNSET:
            raise
        return default
    return cur

