                norm_src = src_enc.lower().replace('-', '')
                norm_dst = to_encoding.lower().replace('-', '')
                if norm_src == norm_dst:
                    return bytes(content)
                # Transcode: decode with detected, encode to requested
                text = content.decode(src_enc, errors='strict')
                return text.encode(to_encoding)
            # Fallback to raw bytes if no detection
            return bytes(content)
        # If somehow not bytes, best-effort conversion to bytes
        return bytes(content)
    except Exception:
        # On any decoding/encoding issue, return the raw bytes
        return bytes(content)

