import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

class TestBSTValidator {

    @Test
    public void testIntegerMaxValueWithRightChild() {
        // This test exposes the critical difference:
        // Previous implementation: isValidBSTHelper(node.right, node.value + 1, maxVal)
        // When node.value = Integer.MAX_VALUE, node.value + 1 overflows to Integer.MIN_VALUE
        // This would make the right child constraint: value must be >= Integer.MIN_VALUE
        // which is always true, allowing invalid BST structures

        // Current implementation: isValidBST(node.right, node.value, upper)
        // Right child must be > Integer.MAX_VALUE, which is impossible, so no right child allowed
        BSTNode root = new BSTNode(Integer.MAX_VALUE);
        root.right = new BSTNode(Integer.MAX_VALUE); // Invalid: right child not > parent
        assertFalse(BSTValidator.isValidBST(root));
    }

    @Test
    public void testIntegerMinValueConstraintHandling() {
        // Previous implementation used node.value + 1 for right subtree lower bound
        // When node.value = Integer.MIN_VALUE, this becomes Integer.MIN_VALUE + 1 = -2147483647
        // Current implementation passes node.value directly as lower bound
        // This creates different constraint behavior
        BSTNode root = new BSTNode(0);
        root.left = new BSTNode(Integer.MIN_VALUE);
        root.left.right = new BSTNode(Integer.MIN_VALUE); // Should be invalid: not > parent
        assertFalse(BSTValidator.isValidBST(root));
    }

    @Test
    public void testNullBoundsVsPrimitiveBounds() {
        // This test shows the difference in bound handling
        // Previous: started with Integer.MIN_VALUE and Integer.MAX_VALUE as bounds
        // Current: starts with null bounds, allowing full integer range
        BSTNode root = new BSTNode(Integer.MIN_VALUE);
        root.right = new BSTNode(Integer.MIN_VALUE + 1);

        // Previous implementation might have issues with the initial bounds
        // Current implementation with null bounds handles this cleanly
        assertTrue(BSTValidator.isValidBST(root));

        // But this should still be invalid
        root.right.left = new BSTNode(Integer.MIN_VALUE); // Not > Integer.MIN_VALUE
        assertFalse(BSTValidator.isValidBST(root));
    }
}

