import os
import json
from collections import Counter


def task_func(directory=None, suffixes=['txt', 'py', 'md']):
    if directory is None:
        directory = os.getcwd()

    allowed = {str(s).lower().lstrip('.') for s in suffixes}
    word_counts = Counter()
    first_prefix = None

    for name in os.listdir(directory):
        full_path = os.path.join(directory, name)
        if not os.path.isfile(full_path):
            continue
        ext = os.path.splitext(name)[1][1:].lower()
        if ext in allowed:
            if first_prefix is None:
                first_prefix = os.path.splitext(name)[0]
            with open(full_path, 'r', encoding='utf-8') as f:
                text = f.read()
            word_counts.update(text.split())

    # Export the aggregated word frequency dictionary to JSON using the first eligible file's prefix
    if first_prefix is not None:
        out_path = os.path.join(directory, f"{first_prefix}.json")
        with open(out_path, 'w', encoding='utf-8') as jf:
            json.dump(dict(word_counts), jf, ensure_ascii=False)

    # Return total number of words
    return sum(word_counts.values())

