import pandas as pd
import numpy as np

def task_func(data_list=[('a', 1, 2.1), ('b', 2, 3.2), ('c', 3, 4.3), ('d', 4, 5.4), ('e', 5, 6.5)]):
    if not data_list:
        return pd.DataFrame({'Mean Value': []})

    # Determine the maximum tuple length and align all tuples by padding with NaN
    max_len = max(len(t) for t in data_list)
    aligned = [list(t) + [np.nan] * (max_len - len(t)) for t in data_list]

    # Transpose to get values per position
    positions = list(zip(*aligned))

    means = []
    for pos_vals in positions:
        # Consider only values whose type is exactly int or float (exclude bool and others), ignore NaN
        filtered = []
        for v in pos_vals:
            if type(v) in (int, float):
                if not pd.isna(v):
                    filtered.append(float(v))
        mean_val = (sum(filtered) / len(filtered)) if filtered else np.nan
        means.append(mean_val)

    index = [f'Position {i+1}' for i in range(len(means))]
    df = pd.DataFrame({'Mean Value': means}, index=index)
    return df

def uppercase_variations(match):
    word = match['token']

    if word.lower() == word:
        return 1

    # Check if word starts with uppercase, ends with uppercase, or is all uppercase
    if len(word) > 0 and (word[0].isupper() or word[-1].isupper() or word.isupper()):
        return 2

    # For any other case, return 1 since we're not implementing full calculation
    return 1

