from datetime import datetime
import numpy as np

def task_func(time_strings):
    fmt = '%d/%m/%y %H:%M:%S.%f'
    n = len(time_strings)
    if n < 2:
        return 0.0
    times = [datetime.strptime(s, fmt) for s in time_strings]
    diffs = [(times[i+1] - times[i]).total_seconds() for i in range(n - 1)]
    if not diffs:
        return 0.0
    return float(np.mean(diffs))

