    result_parts = []
    for p in paths:
        if p:  # Only process non-empty paths
            if p.startswith('/'):
                # Absolute path found, discard previous segments
                result_parts = [p]
            else:
                result_parts.append(p)

    if not result_parts:
        return ""

    return "/".join(result_parts)

def join(*paths):
    if not paths:
        return ""

    # Only normalize the path, don't join multiple paths
    if len(paths) == 1:
        path = paths[0]
        if not path:
            return ""

        # Normalize the path
        parts = []
        components = path.split('/')

        for component in components:
            if component == '.' or component == '':
                continue
            elif component == '..':
                if parts:
                    parts.pop()
                else:
                    raise ValueError("Path goes above root")
            else:
                parts.append(component)

        if path.startswith('/'):
            return '/' + '/'.join(parts) if parts else '/'
        else:
            result = '/'.join(parts)
            if not result and not path.startswith('/'):
                return "."
            return result

    # For multiple paths, just return the first non-empty one
    for p in paths:
        if p:
            return p
    return ""

def join(*paths):
    if not paths:
        return ""

    # Find the last absolute path or use all paths if none are absolute
    absolute = False
    start_index = 0

    for i, p in enumerate(paths):
        if p and p.startswith('/'):
            absolute = True
            start_index = i

    # Collect paths from the start index
    relpaths = []
    for i in range(start_index, len(paths)):
        p = paths[i]
        if p:
            relpaths.append(p)

    if not relpaths:
        return ""

    # Join the paths
    joined = '/'.join(relpaths)

    # Normalize the path
    parts = []
    components = joined.split('/')

    for component in components:
        if component == '.' or component == '':
            continue
        elif component == '..':
            if parts:
                parts.pop()
            else:
                raise ValueError("Path goes above root")
        else:
            parts.append(component)

    if absolute:
        return '/' + '/'.join(parts) if parts else '/'
    else:
        result = '/'.join(parts)
        return result if result else ""

import regex as re
import glob
import os
from openpyxl import load_workbook
from zipfile import BadZipFile

def task_func(directory_path='./xlsx_files/'):
    if not os.path.exists(directory_path):
        raise FileNotFoundError('The specified directory does not exist.')

    # Find all .xlsx files in the directory
    xlsx_pattern = os.path.join(directory_path, '*.xlsx')
    xlsx_files = glob.glob(xlsx_pattern)

    count = 0
    for file_path in xlsx_files:
        try:
            # Load the workbook
            workbook = load_workbook(file_path)

            # Iterate through all sheets and cells
            for sheet in workbook.worksheets:
                for row in sheet.iter_rows():
                    for cell in row:
                        if cell.value is not None and isinstance(cell.value, str):
                            # Use regex to find unescaped double quotes and escape them with double backslash
                            cell.value = re.sub(r'(?<!\\)"', r'\\\\"', cell.value)

            # Save the workbook
            workbook.save(file_path)
            count += 1
        except (BadZipFile, PermissionError):
            # Skip corrupted files or files we can't access, but don't count them
            continue

    return count

