import java.lang.reflect.Array;
import java.lang.reflect.Field;
import java.util.*;

public class ObjectInspector {
    public Map<String, Object> inspectObject(Object obj) {
        return inspectObject(obj, Integer.MAX_VALUE);
    }

    public Map<String, Object> inspectObject(Object obj, int maxDepth) {
        Map<String, Object> result = new HashMap<>();

        if (obj == null) {
            result.put("value", null);
        } else if (obj.getClass().isArray()) {
            if (maxDepth <= 0) {
                result.put("type", obj.getClass().getSimpleName());
                result.put("value", "<max depth reached>");
            } else {
                result.put("type", obj.getClass().getComponentType().getSimpleName() + "[]");
                int length = Array.getLength(obj);
                List<Map<String, Object>> elements = new ArrayList<>();
                for (int i = 0; i < length; i++) {
                    Object element = Array.get(obj, i);
                    elements.add(inspectObject(element, maxDepth - 1));
                }
                result.put("value", elements);
            }
        } else {
            result.put("type", obj.getClass().getSimpleName());

            if (isSimpleType(obj)) {
                result.put("value", obj);
            } else if (maxDepth > 0) {
                // Handle complex objects
                Map<String, Object> fieldsMap = new HashMap<>();
                List<Field> allFields = getAllFields(obj.getClass());

                for (Field field : allFields) {
                    // Skip static fields
                    if (java.lang.reflect.Modifier.isStatic(field.getModifiers())) {
                        continue;
                    }

                    try {
                        field.setAccessible(true);
                        Object fieldValue = field.get(obj);
                        fieldsMap.put(field.getName(), inspectObject(fieldValue, maxDepth - 1));
                    } catch (IllegalAccessException e) {
                        // Handle inaccessible fields
                        fieldsMap.put(field.getName(), "<inaccessible>");
                    }
                }

                result.put("fields", fieldsMap);
            } else {
                result.put("value", "<max depth reached>");
            }
        }

        return result;
    }

    private boolean isSimpleType(Object obj) {
        return obj instanceof String ||
               obj instanceof Number ||
               obj instanceof Boolean ||
               obj instanceof Character;
    }

    public List<Field> getAllFields(Class<?> clazz) {
        List<Field> fields = new ArrayList<>();
        while (clazz != null) {
            Field[] declaredFields = clazz.getDeclaredFields();
            for (Field field : declaredFields) {
                // Skip static fields
                if (!java.lang.reflect.Modifier.isStatic(field.getModifiers())) {
                    fields.add(field);
                }
            }
            clazz = clazz.getSuperclass();
        }
        return fields;
    }

    public Map<String, Object> createSimpleFieldMap(Object obj) {
        Map<String, Object> result = new HashMap<>();
        if (obj == null) {
            result.put("value", null);
        } else if (isSimpleType(obj)) {
            result.put("type", obj.getClass().getSimpleName());
            result.put("value", obj);
        }
        // For complex objects, return an empty map (no type or value)
        return result;
    }
}

