        if (isAboveFloor[i] && !selected[i]) {
            unused.add(nodeIds[i], approximateScoresById.get(nodeIds[i]));
        }
    }

    // Return worst approximate score among selected topK using the map
    if (selectedCount < topK) {
        return Float.POSITIVE_INFINITY;
    }

    float worstApproximate = Float.POSITIVE_INFINITY;
    for (int i = 0; i < size(); i++) {
        if (selected[i]) {
            worstApproximate = Math.min(worstApproximate, approximateScoresById.get(nodeIds[i]));
        }
    }

    return worstApproximate;
}

