                graph.layers.get(level).replaceDeletedNeighbors(node, toDelete, candidates);
            });
        }).join();
    }

    // Handle entry point update if it was deleted
    if (toDelete.get(graph.entry().node)) {
        int newLevel = graph.getMaxLevel();
